create or replace function public.create_knowledge_article_version(target_article_id uuid,target_content text,target_change_reason text) returns uuid language plpgsql security definer set search_path=public as $$ declare article public.knowledge_articles%rowtype; version_id uuid; next_version integer; begin select * into article from public.knowledge_articles where id=target_article_id for update; if article.id is null or not public.has_organization_role(article.organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER']::public.platform_role[]) then raise exception 'KNOWLEDGE_NOT_AUTHORIZED'; end if; if article.status not in('DRAFT','PUBLISHED') then raise exception 'KNOWLEDGE_INVALID_STATE'; end if; if length(trim(target_content)) not between 10 and 50000 or length(trim(target_change_reason)) not between 5 and 1000 then raise exception 'KNOWLEDGE_INVALID_INPUT'; end if; next_version:=article.current_version+1; insert into public.knowledge_article_versions(article_id,organization_id,version_number,content,change_reason,created_by) values(article.id,article.organization_id,next_version,trim(target_content),trim(target_change_reason),auth.uid()) returning id into version_id; update public.knowledge_articles set current_version=next_version,status='DRAFT' where id=article.id; insert into public.audit_logs(organization_id,actor_id,action,entity_type,entity_id,after_value,source) values(article.organization_id,auth.uid(),'KNOWLEDGE_ARTICLE_VERSION_CREATED','knowledge_article',article.id,jsonb_build_object('version',next_version),'WEB'); return version_id; end; $$;
revoke all on function public.create_knowledge_article_version(uuid,text,text) from public; grant execute on function public.create_knowledge_article_version(uuid,text,text) to authenticated;
